import java.io.*;
import java.util.*;

public class CF998B {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.parseNumbers();
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int w = (int) in.nval;
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            a[i] = (int) in.nval;
        }
        ArrayList<Integer> cuts = new ArrayList<Integer>();
        int even = 0;
        int odd = 0;
        for (int i = 0; i < n - 1; i++) {
            if ((a[i] & 1) == 0) even++;
            else odd++;
            if (even == odd) cuts.add(Math.abs(a[i] - a[i + 1]));
        }
        int[] prev = new int[w + 1];
        int[] cur = new int[w + 1];
        for (int i = 1; i <= cuts.size(); i++) {
            int cost = cuts.get(i - 1);
            for (int j = 1; j <= w; j++) {
                if (cost <= j) {
                    cur[j] = Math.max(1 + prev[j - cost], prev[j]);
                } else {
                    cur[j] = prev[j];
                }
            }
            int[] tmp = prev;
            prev = cur;
            cur = tmp;
        }
        PrintWriter out = new PrintWriter(System.out);
        out.println(prev[w]);
        out.close();
    }
}
